import json
splits = {}
for name in ['swebench_train', 'swebench_val', 'swebench_test']:
    path = f'/home/sonny/exec-sim-repair-verifier/data/swebench_full/{name}.jsonl'
    ids = set()
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            ids.add(d['problem_id'])
    splits[name] = ids
    print(f'{name}: {len(ids)} unique problem_ids')

# Check overlaps
for a in splits:
    for b in splits:
        if a < b:
            overlap = splits[a] & splits[b]
            print(f'{a} & {b} overlap: {len(overlap)}')

all_ids = set()
for v in splits.values():
    all_ids |= v
print(f'Total unique problem_ids: {len(all_ids)}')
"

